export const deleteBooking = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid Id",
        success: false
      })
    }
    const operation = await Booking.findByIdAndDelete(id);
    if (!operation) {
      return res.status(404).json({
        message: "Data not exist in DB",
        success: false
      })
    }
    return res.status(200).json({
      message: "Deleted Data Successfully",
      success: true,
      data: operation
    })
  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while deleting Data",
      success: false,
      error: error.message
    })
  }
}


export const updateBooking = async (req, res) => {
  try {
    const { id } = req.params;
    if (!isValidObjectId(id)) {
      return res.status(404).json({
        message: "Invalid Id",
        success: false
      })
    }
    const data = {
      fair_id: req.body.fair_id,
      from: req.body.from,
      to: req.body.to,
      customer: req.body.customer,
      driver: req.body.driver,
      vehicle: req.body.vehicle,
      booking_start_date: req.body.booking_start_date,
      booking_end_date: req.body.booking_end_date,
    }

    const response = await Booking.findByIdAndUpdate(id, data, { new: true });
    if (response) {
      return res.status(200).json({
        message: "Booking updated successfully",
        success: true,
        data: response
      })
    }

  } catch (error) {
    console.log(error);
    return res.status(404).json({
      message: "Error while Updating Data",
      success: false,
      error: error.message
    })
  }

}